//! Minimal logging compatible with `log` crate interface used elsewhere.
use std::sync::atomic::{AtomicU8, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

static LEVEL: AtomicU8 = AtomicU8::new(LEVEL_WARN);

pub const LEVEL_ERROR: u8 = 1;
pub const LEVEL_WARN: u8 = 2;
pub const LEVEL_INFO: u8 = 3;
pub const LEVEL_DEBUG: u8 = 4;
#[allow(dead_code)]
pub const LEVEL_TRACE: u8 = 5;

pub fn init(verbose: u8) {
    let level = match verbose {
        0 => LEVEL_WARN,
        1 => LEVEL_INFO,
        _ => LEVEL_DEBUG,
    };
    LEVEL.store(level, Ordering::Relaxed);
}

pub fn enabled(level: u8) -> bool {
    LEVEL.load(Ordering::Relaxed) >= level
}

fn ts() -> String {
    // Format as HH:MM:SS in local time.
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = dur.as_secs() as i64;
    // We need local time. Use a libc-free approach: read TZ? Too complex.
    // Use the libc timezone via /etc/localtime or fall back to UTC offset 0.
    let offset_secs = local_offset_secs();
    let adj = secs + offset_secs as i64;
    let t = adj.rem_euclid(86400);
    let h = (t / 3600) as u32;
    let m = ((t % 3600) / 60) as u32;
    let s = (t % 60) as u32;
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn local_offset_secs() -> i32 {
    // Use libc localtime_r if available via FFI. Here we try a simple approach
    // using libc via raw syscall. For simplicity we just use the "TZ"/offset
    // stored by libc through std::time::SystemTime — but std doesn't expose it.
    // Use a small libc FFI.
    extern "C" {
        fn time(t: *mut i64) -> i64;
        fn localtime_r(t: *const i64, tm: *mut libc_tm) -> *mut libc_tm;
    }
    #[repr(C)]
    #[derive(Default)]
    struct libc_tm {
        tm_sec: i32,
        tm_min: i32,
        tm_hour: i32,
        tm_mday: i32,
        tm_mon: i32,
        tm_year: i32,
        tm_wday: i32,
        tm_yday: i32,
        tm_isdst: i32,
        tm_gmtoff: i64,
        tm_zone: *const u8,
    }
    unsafe {
        let mut now: i64 = 0;
        time(&mut now);
        let mut t = libc_tm::default();
        if localtime_r(&now, &mut t).is_null() {
            0
        } else {
            t.tm_gmtoff as i32
        }
    }
}

macro_rules! impl_log {
    ($name:ident, $level:expr, $label:expr) => {
        #[macro_export]
        macro_rules! $name {
            ($$($$arg:tt)*) => {
                if $crate::logger::enabled($level) {
                    eprintln!("{} [{}] {}", $crate::logger::ts_str(), $label, format!($$($$arg)*));
                }
            };
        }
    };
}

pub fn ts_str() -> String {
    ts()
}

// Export a minimal subset re-exported as `log::*` for callers in this crate.
pub mod log {
    pub fn enabled_info() -> bool {
        super::enabled(super::LEVEL_INFO)
    }
    pub fn enabled_debug() -> bool {
        super::enabled(super::LEVEL_DEBUG)
    }
    pub fn enabled_warn() -> bool {
        super::enabled(super::LEVEL_WARN)
    }
    pub fn enabled_error() -> bool {
        super::enabled(super::LEVEL_ERROR)
    }
}
