//! Minimal logging compatible with the `log`-style interface used in xcp.
use std::sync::atomic::{AtomicU8, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

static LEVEL: AtomicU8 = AtomicU8::new(LEVEL_WARN);

pub const LEVEL_ERROR: u8 = 1;
pub const LEVEL_WARN: u8 = 2;
pub const LEVEL_INFO: u8 = 3;
pub const LEVEL_DEBUG: u8 = 4;

pub fn init(verbose: u8) {
    let level = match verbose {
        0 => LEVEL_WARN,
        1 => LEVEL_INFO,
        _ => LEVEL_DEBUG,
    };
    LEVEL.store(level, Ordering::Relaxed);
}

pub fn enabled(level: u8) -> bool {
    LEVEL.load(Ordering::Relaxed) >= level
}

pub fn ts() -> String {
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = dur.as_secs() as i64;
    let offset_secs = local_offset_secs();
    let adj = secs + offset_secs as i64;
    let t = adj.rem_euclid(86400);
    let h = (t / 3600) as u32;
    let m = ((t % 3600) / 60) as u32;
    let s = (t % 60) as u32;
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn local_offset_secs() -> i32 {
    #[repr(C)]
    struct LibcTm {
        tm_sec: i32,
        tm_min: i32,
        tm_hour: i32,
        tm_mday: i32,
        tm_mon: i32,
        tm_year: i32,
        tm_wday: i32,
        tm_yday: i32,
        tm_isdst: i32,
        tm_gmtoff: i64,
        tm_zone: *const u8,
    }
    extern "C" {
        fn time(t: *mut i64) -> i64;
        fn localtime_r(t: *const i64, tm: *mut LibcTm) -> *mut LibcTm;
    }
    unsafe {
        let mut now: i64 = 0;
        time(&mut now);
        let mut tm = LibcTm {
            tm_sec: 0, tm_min: 0, tm_hour: 0, tm_mday: 0, tm_mon: 0, tm_year: 0,
            tm_wday: 0, tm_yday: 0, tm_isdst: 0, tm_gmtoff: 0, tm_zone: std::ptr::null(),
        };
        if localtime_r(&now, &mut tm).is_null() {
            0
        } else {
            tm.tm_gmtoff as i32
        }
    }
}

pub fn log_message(level: u8, label: &str, msg: &str) {
    if enabled(level) {
        eprintln!("{} [{}] {}", ts(), label, msg);
    }
}

pub mod log {
    pub fn info(args: std::fmt::Arguments) {
        super::log_message(super::LEVEL_INFO, "INFO", &format!("{}", args));
    }
    pub fn warn(args: std::fmt::Arguments) {
        super::log_message(super::LEVEL_WARN, "WARN", &format!("{}", args));
    }
    pub fn error(args: std::fmt::Arguments) {
        super::log_message(super::LEVEL_ERROR, "ERROR", &format!("{}", args));
    }
    pub fn debug(args: std::fmt::Arguments) {
        super::log_message(super::LEVEL_DEBUG, "DEBUG", &format!("{}", args));
    }
}

#[macro_export]
macro_rules! log_info {
    ($($arg:tt)*) => { $crate::logger::log::info(format_args!($($arg)*)); };
}
#[macro_export]
macro_rules! log_warn {
    ($($arg:tt)*) => { $crate::logger::log::warn(format_args!($($arg)*)); };
}
#[macro_export]
macro_rules! log_error {
    ($($arg:tt)*) => { $crate::logger::log::error(format_args!($($arg)*)); };
}
#[macro_export]
macro_rules! log_debug {
    ($($arg:tt)*) => { $crate::logger::log::debug(format_args!($($arg)*)); };
}

// Create an alias for callers using `log::` paths.
pub use log as log_fns;
