//! Parse strings like "1MB", "1KiB" etc. into byte counts.
use std::fmt;

#[derive(Debug)]
pub enum ByteSizeError {
    InvalidFormat,
    OutOfRange,
}

impl fmt::Display for ByteSizeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("could not interpret string as byte size")
    }
}

/// Parse a size string. Accepts forms like:
///   - "1024"            => 1024
///   - "1K", "1KB", "1KiB" => 1024
///   - "1M", "1MB", "1MiB" => 1024*1024
///   - "1GB", "1TB", etc.
/// Case-insensitive, may include (no) spaces between number and unit, and
/// allows optional 'B' after the unit prefix.
pub fn parse_bytes(input: &str) -> Result<u64, ByteSizeError> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(ByteSizeError::InvalidFormat);
    }

    // Split number from suffix.
    let bytes = trimmed.as_bytes();
    let mut i = 0;
    // Sign not allowed.
    if bytes[i] == b'+' || bytes[i] == b'-' {
        return Err(ByteSizeError::InvalidFormat);
    }
    // Accept digits (and a decimal point, for unbytify-style sizes like "1.5M")
    let mut had_digit = false;
    let mut had_dot = false;
    while i < bytes.len() {
        let c = bytes[i];
        if c.is_ascii_digit() {
            had_digit = true;
            i += 1;
        } else if c == b'.' && !had_dot {
            had_dot = true;
            i += 1;
        } else {
            break;
        }
    }
    if !had_digit {
        return Err(ByteSizeError::InvalidFormat);
    }
    let (num_str, rest) = trimmed.split_at(i);
    let num: f64 = num_str.parse().map_err(|_| ByteSizeError::InvalidFormat)?;

    let suffix: String = rest.trim().to_ascii_lowercase();
    let multiplier: u64 = match suffix.as_str() {
        "" | "b" => 1,
        "k" | "kb" | "kib" => 1024,
        "m" | "mb" | "mib" => 1024 * 1024,
        "g" | "gb" | "gib" => 1024u64.pow(3),
        "t" | "tb" | "tib" => 1024u64.pow(4),
        "p" | "pb" | "pib" => 1024u64.pow(5),
        "e" | "eb" | "eib" => 1024u64.pow(6),
        _ => return Err(ByteSizeError::InvalidFormat),
    };

    let bytes = num * multiplier as f64;
    if !bytes.is_finite() || bytes < 0.0 || bytes > u64::MAX as f64 {
        return Err(ByteSizeError::OutOfRange);
    }
    Ok(bytes as u64)
}
