//! Minimal path globbing support similar to unix shell globbing.
//! Supports `*`, `?`, `[..]` character classes, and `**` for recursive.
use std::path::{Component, Path, PathBuf};

pub fn has_glob_chars(s: &str) -> bool {
    s.chars().any(|c| matches!(c, '*' | '?' | '['))
}

pub fn expand(pattern: &str) -> Vec<PathBuf> {
    if !has_glob_chars(pattern) {
        let p = PathBuf::from(pattern);
        if p.exists() {
            return vec![p];
        }
        return vec![];
    }
    let p = Path::new(pattern);
    let mut components: Vec<String> = Vec::new();
    let mut abs = false;
    for c in p.components() {
        match c {
            Component::RootDir => abs = true,
            Component::CurDir => {}
            Component::Normal(s) => components.push(s.to_string_lossy().into_owned()),
            Component::ParentDir => components.push("..".to_string()),
            Component::Prefix(_) => {}
        }
    }
    let start = if abs {
        PathBuf::from("/")
    } else {
        PathBuf::from(".")
    };
    let mut out = Vec::new();
    walk(&start, &components, 0, abs, &mut out);
    out
}

fn walk(base: &Path, comps: &[String], idx: usize, abs: bool, out: &mut Vec<PathBuf>) {
    if idx >= comps.len() {
        let p = if abs {
            base.to_path_buf()
        } else {
            // strip leading "./" prefix
            if base == Path::new(".") {
                return;
            }
            base.strip_prefix("./").map(|p| p.to_path_buf()).unwrap_or_else(|_| base.to_path_buf())
        };
        out.push(p);
        return;
    }
    let pat = &comps[idx];

    if pat == "**" {
        // Match any number of path components, including zero.
        // First, match zero directories.
        walk(base, comps, idx + 1, abs, out);
        // Then recurse into each subdirectory and keep expanding "**".
        if let Ok(entries) = std::fs::read_dir(base) {
            for e in entries.flatten() {
                let p = e.path();
                if p.is_dir() {
                    walk(&p, comps, idx, abs, out);
                }
            }
        }
        return;
    }

    if !has_glob_chars(pat) {
