//! Minimal .gitignore parser. Supports:
//!   - Blank lines and `#` comments
//!   - Negation with `!`
//!   - Rooted patterns (those with a leading `/` or containing a `/`)
//!   - Patterns ending with `/` (directory-only)
//!   - Wildcards `*`, `?`, `[..]`
use crate::glob::matches_pattern;
use std::path::Path;

#[derive(Debug, Clone)]
pub struct Pattern {
    pub negation: bool,
    pub directory_only: bool,
    /// When true, matches only at the repository root; otherwise match at any depth.
    pub anchored: bool,
    /// The path segments of the pattern (between '/' separators).
    pub segments: Vec<String>,
}

#[derive(Debug, Clone, Default)]
pub struct GitIgnore {
    pub patterns: Vec<Pattern>,
}

impl GitIgnore {
    pub fn parse(text: &str) -> Self {
        let mut patterns = Vec::new();
        for raw in text.lines() {
            let trimmed = raw.trim_end();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            let mut s = trimmed;
            let mut negation = false;
            if s.starts_with('!') {
                negation = true;
                s = &s[1..];
            }
            let mut directory_only = false;
            if s.ends_with('/') {
                directory_only = true;
                s = &s[..s.len() - 1];
            }
            // Leading slash => anchored to root.
            let mut anchored = false;
            if s.starts_with('/') {
                anchored = true;
                s = &s[1..];
            }
            // If pattern contains '/' after stripping, it's anchored relative to root.
            if s.contains('/') {
                anchored = true;
            }
            let segments: Vec<String> = s.split('/').map(|s| s.to_string()).collect();
            patterns.push(Pattern { negation, directory_only, anchored, segments });
        }
        GitIgnore { patterns }
    }

    /// Check if a path should be ignored. `rel_path` is relative to the
    /// repository root, `is_dir` indicates whether it's a directory.
    pub fn is_ignored(&self, rel_path: &Path, is_dir: bool) -> bool {
        let parts: Vec<String> = rel_path
            .components()
            .map(|c| c.as_os_str().to_string_lossy().into_owned())
            .collect();
        let mut ignored = false;
        for p in &self.patterns {
            if p.directory_only && !is_dir {
                continue;
            }
            if match_pattern(p, &parts) {
                ignored = !p.negation;
            }
        }
        ignored
    }
}

fn match_pattern(p: &Pattern, parts: &[String]) -> bool {
    let segs = &p.segments;
    if segs.is_empty() {
        return false;
    }
    if p.anchored {
        if parts.len() < segs.len() {
            return false;
