    pub no_perms: bool,
    pub no_timestamps: bool,
    pub ownership: bool,
    pub driver: Driver,
    pub no_target_directory: bool,
    pub target_directory: Option<PathBuf>,
    pub fsync: bool,
    pub reflink: Reflink,
    pub backup: Backup,
    pub paths: Vec<PathBuf>,
}

pub enum ParseResult {
    Ok(Options),
    Help(String),
    Version(String),
    ClapError(String),
    AppError(String),
}

fn prog_from(argv0: &OsString) -> String {
    let s = argv0.to_string_lossy();
    let p = std::path::Path::new(s.as_ref());
    p.file_name()
        .map(|f| f.to_string_lossy().into_owned())
        .unwrap_or_else(|| s.into_owned())
}

pub fn parse_args(argv: Vec<OsString>) -> ParseResult {
    let prog = if argv.is_empty() {
        PROG_NAME.to_string()
    } else {
        prog_from(&argv[0])
    };

    let mut opts = Options {
        verbose: 0,
        recursive: false,
        dereference: false,
        workers: 4,
        block_size: 1024 * 1024, // 1MB default
        no_clobber: false,
        force: false,
        gitignore: false,
        glob: false,
        no_progress: false,
        no_perms: false,
        no_timestamps: false,
        ownership: false,
        driver: Driver::ParFile,
        no_target_directory: false,
        target_directory: None,
        fsync: false,
        reflink: Reflink::Auto,
        backup: Backup::None,
        paths: Vec::new(),
    };

    let mut positional_only = false;
    let mut args_iter = argv.into_iter();
    let _argv0 = args_iter.next();
    let args: Vec<OsString> = args_iter.collect();
    let mut i = 0;
    while i < args.len() {
        let cur = args[i].clone();
        let cur_s = cur.to_string_lossy().into_owned();

        if positional_only {
            opts.paths.push(PathBuf::from(cur));
            i += 1;
            continue;
        }

        if cur_s == "--" {
            positional_only = true;
            i += 1;
            continue;
        }

        // Long options.
        if cur_s.starts_with("--") {
            let body = &cur_s[2..];
            let (name, value_inline): (&str, Option<String>) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            // dispatch
            match name {
                "help" => {
                    if value_inline.is_some() {
                        return ParseResult::ClapError(fmt_bool_with_value_err(
                            &prog, "--help", value_inline.as_deref().unwrap_or(""),
                        ));
                    }
                    return ParseResult::Help(long_help(&prog));
                }
                "version" => {
                    if value_inline.is_some() {
                        return ParseResult::ClapError(fmt_bool_with_value_err(
                            &prog, "--version", value_inline.as_deref().unwrap_or(""),
                        ));
                    }
                    return ParseResult::Version(version_text());
                }
                "verbose" => {
                    if value_inline.is_some() {
                        return ParseResult::ClapError(fmt_bool_with_value_err(
                            &prog, "--verbose", value_inline.as_deref().unwrap_or(""),
                        ));
                    }
                    opts.verbose = opts.verbose.saturating_add(1);
                }
                "recursive" => { opts.recursive = true; bool_check(&prog, "--recursive", &value_inline)?; }
                "dereference" => { opts.dereference = true; bool_check(&prog, "--dereference", &value_inline)?; }
                "workers" => {
                    let val = take_value(&mut i, &args, &cur_s, &value_inline, &prog)?;
                    match val.parse::<i64>() {
                        Ok(v) => opts.workers = v,
                        Err(e) => return ParseResult::ClapError(fmt_invalid_value(
                            &prog, "--workers <WORKERS>", &val, &e.to_string()
                        )),
                    }
                }
                "block-size" => {
                    let val = take_value(&mut i, &args, &cur_s, &value_inline, &prog)?;
                    match bytesize::parse_bytes(&val) {
                        Ok(v) => opts.block_size = v,
                        Err(e) => return ParseResult::ClapError(fmt_invalid_value(
                            &prog, "--block-size <BLOCK_SIZE>", &val, &e.to_string()
                        )),
                    }
                }
                "no-clobber" => { opts.no_clobber = true; bool_check(&prog, "--no-clobber", &value_inline)?; }
                "force" => { opts.force = true; bool_check(&prog, "--force", &value_inline)?; }
                "gitignore" => { opts.gitignore = true; bool_check(&prog, "--gitignore", &value_inline)?; }
                "glob" => { opts.glob = true; bool_check(&prog, "--glob", &value_inline)?; }
                "no-progress" => { opts.no_progress = true; bool_check(&prog, "--no-progress", &value_inline)?; }
                "no-perms" => { opts.no_perms = true; bool_check(&prog, "--no-perms", &value_inline)?; }
                "no-timestamps" => { opts.no_timestamps = true; bool_check(&prog, "--no-timestamps", &value_inline)?; }
                "ownership" => { opts.ownership = true; bool_check(&prog, "--ownership", &value_inline)?; }
                "driver" => {
                    let val = take_value(&mut i, &args, &cur_s, &value_inline, &prog)?;
                    opts.driver = match val.as_str() {
                        "parfile" => Driver::ParFile,
                        "parblock" => Driver::ParBlock,
                        _ => return ParseResult::ClapError(fmt_invalid_value(
                            &prog, "--driver <DRIVER>", &val, &format!("Unknown driver: {}", val),
                        )),
                    };
                }
                "no-target-directory" => { opts.no_target_directory = true; bool_check(&prog, "--no-target-directory", &value_inline)?; }
                "target-directory" => {
                    let val = take_value(&mut i, &args, &cur_s, &value_inline, &prog)?;
                    opts.target_directory = Some(PathBuf::from(val));
                }
                "fsync" => { opts.fsync = true; bool_check(&prog, "--fsync", &value_inline)?; }
                "reflink" => {
                    let val = take_value(&mut i, &args, &cur_s, &value_inline, &prog)?;
                    opts.reflink = match val.as_str() {
                        "auto" => Reflink::Auto,
                        "always" => Reflink::Always,
                        "never" => Reflink::Never,
                        _ => return ParseResult::ClapError(fmt_invalid_value(
                            &prog, "--reflink <REFLINK>", &val,
                            &format!("Invalid arguments: Unexpected value for 'reflink': {}", val),
                        )),
                    };
                }
                "backup" => {
                    let val = take_value(&mut i, &args, &cur_s, &value_inline, &prog)?;
                    opts.backup = match val.as_str() {
                        "none" | "off" => Backup::None,
                        "numbered" => Backup::Numbered,
                        "auto" => Backup::Auto,
                        _ => return ParseResult::ClapError(fmt_invalid_value(
                            &prog, "--backup <BACKUP>", &val,
                            &format!("Invalid arguments: Unexpected value for 'backup': {}", val),
                        )),
                    };
                }
                _ => return ParseResult::ClapError(fmt_unknown_arg(&prog, &cur_s)),
            }
            i += 1;
            continue;
        }

        // Short options (possibly clustered).
        if cur_s.starts_with('-') && cur_s.len() > 1 {
            // Starting with '-' but also could be a value or negative number.
            // If it's an unknown pattern or looks like a flag cluster, parse as flags.
            let rest = &cur_s[1..];
            // Handle clusters like -vvv, -rT, -rn etc.
            let chars: Vec<char> = rest.chars().collect();
            let mut idx = 0;
            let mut consumed_arg = false;
            while idx < chars.len() {
                let ch = chars[idx];
                match ch {
                    'h' => return ParseResult::Help(short_help(&prog)),
                    'V' => return ParseResult::Version(version_text()),
                    'v' => opts.verbose = opts.verbose.saturating_add(1),
                    'r' => opts.recursive = true,
                    'L' => opts.dereference = true,
                    'n' => opts.no_clobber = true,
                    'f' => opts.force = true,
                    'g' => opts.glob = true,
                    'o' => opts.ownership = true,
                    'T' => opts.no_target_directory = true,
                    'w' => {
                        // short-form with value; rest after this char or next arg.
                        let remaining: String = chars[idx + 1..].iter().collect();
                        let val = if !remaining.is_empty() {
                            idx = chars.len(); // consume all
                            remaining
                        } else {
                            i += 1;
                            consumed_arg = true;
                            if i >= args.len() {
                                return ParseResult::ClapError(fmt_missing_value(&prog, "--workers <WORKERS>"));
                            }
                            args[i].to_string_lossy().into_owned()
                        };
                        match val.parse::<i64>() {
                            Ok(v) => opts.workers = v,
                            Err(e) => return ParseResult::ClapError(fmt_invalid_value(
                                &prog, "--workers <WORKERS>", &val, &e.to_string()
                            )),
                        }
                        if idx >= chars.len() { break; }
                    }
                    _ => {
                        return ParseResult::ClapError(fmt_unknown_arg(&prog, &cur_s));
                    }
                }
                idx += 1;
            }
            if !consumed_arg {
                i += 1;
            } else {
                i += 1;
            }
            continue;
        }

        // Positional arg.
        opts.paths.push(PathBuf::from(cur));
        i += 1;
    }

    // Validate flag combos.
    if opts.no_clobber && opts.force {
        return ParseResult::AppError(
            "Invalid arguments: --force and --noclobber cannot be set at the same time.".to_string()
        );
    }

    ParseResult::Ok(opts)
}

fn take_value(
    i: &mut usize,
    args: &[OsString],
    cur_s: &str,
    inline: &Option<String>,
    prog: &str,
) -> Result<String, ParseResultShortcut> {
    if let Some(v) = inline {
        return Ok(v.clone());
    }
    *i += 1;
    if *i >= args.len() {
        return Err(ParseResultShortcut::ClapErr(fmt_missing_value(prog, &option_spec_for(cur_s))));
    }
    Ok(args[*i].to_string_lossy().into_owned())
}

/// A small helper that lets the `?` operator return a parse error.
enum ParseResultShortcut {
    ClapErr(String),
}

impl From<ParseResultShortcut> for ParseResult {
    fn from(s: ParseResultShortcut) -> Self {
        match s {
            ParseResultShortcut::ClapErr(msg) => ParseResult::ClapError(msg),
        }
    }
}

// Re-export the ? behaviour on ParseResult via the Try trait? Easier: use a
// dedicated helper macro.

fn bool_check(prog: &str, name: &str, val: &Option<String>) -> Result<(), ParseResultShortcut> {
    if let Some(v) = val {
        return Err(ParseResultShortcut::ClapErr(fmt_bool_with_value_err(prog, name, v)));
    }
    Ok(())
}

