// Clap-like error formatting -------------------------------------------------

fn fmt_unknown_arg(prog: &str, arg: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!("error: unexpected argument '{}' found\n\n", arg));
    out.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", arg, arg));
    out.push_str(&format!("Usage: {} [OPTIONS] [PATHS]...\n\n", prog));
    out.push_str("For more information, try '--help'.\n");
    out
}

fn fmt_invalid_value(prog: &str, spec: &str, val: &str, err: &str) -> String {
    // spec is like "--workers <WORKERS>", usage line shows the option only.
    let opt = spec.split_whitespace().next().unwrap_or(spec);
    let mut out = String::new();
    out.push_str(&format!(
        "error: invalid value '{}' for '{}': {}\n\n",
        val, spec, err
    ));
    out.push_str(&format!("For more information, try '--help'.\n"));
    let _ = opt; // unused variant
    out
}

fn fmt_missing_value(prog: &str, spec: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "error: a value is required for '{}' but none was supplied\n\n",
        spec
    ));
    out.push_str("For more information, try '--help'.\n");
    let _ = prog;
    out
}

fn fmt_bool_with_value_err(prog: &str, name: &str, val: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "error: unexpected value '{}' for '{}' found; no more were expected\n\n",
        val, name
    ));
    out.push_str(&format!("Usage: {} {} [PATHS]...\n\n", prog, name));
    out.push_str("For more information, try '--help'.\n");
    out
}

