pub fn long_help(prog: &str) -> String {
    let mut s = String::new();
    s.push_str(ABOUT);
    s.push_str("\n\n");
    s.push_str(&format!("Usage: {} [OPTIONS] [PATHS]...\n\n", prog));
    s.push_str("Arguments:\n");
    s.push_str("  [PATHS]...\n");
    s.push_str("          Path list.\n");
