//! Command line parsing that mimics clap-derived output.
use std::ffi::OsString;
use std::path::PathBuf;

use crate::bytesize;

pub const PROG_NAME: &str = "xcp";
pub const VERSION: &str = "0.24.3";
pub const ABOUT: &str = "A (partial) clone of the Unix `cp` command with progress and pluggable drivers.";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Reflink {
    Auto,
    Always,
    Never,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Backup {
    None,
    Numbered,
    Auto,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Driver {
    ParFile,
    ParBlock,
}

#[derive(Debug, Clone)]
pub struct Options {
    pub verbose: u8,
    pub recursive: bool,
    pub dereference: bool,
    pub workers: i64,
    pub block_size: u64,
    pub no_clobber: bool,
    pub force: bool,
    pub gitignore: bool,
    pub glob: bool,
    pub no_progress: bool,
    pub no_perms: bool,
    pub no_timestamps: bool,
    pub ownership: bool,
    pub driver: Driver,
    pub no_target_directory: bool,
    pub target_directory: Option<PathBuf>,
    pub fsync: bool,
    pub reflink: Reflink,
    pub backup: Backup,
    pub paths: Vec<PathBuf>,
}

pub enum ParseResult {
    Ok(Options),
    Help(String),
    Version(String),
    ClapError(String),
    AppError(String),
}

fn prog_from(argv0: &OsString) -> String {
    let s = argv0.to_string_lossy();
    let p = std::path::Path::new(s.as_ref());
    p.file_name()
        .map(|f| f.to_string_lossy().into_owned())
        .unwrap_or_else(|| s.into_owned())
}

pub fn parse_args(argv: Vec<OsString>) -> ParseResult {
    let prog = if argv.is_empty() {
        PROG_NAME.to_string()
    } else {
        prog_from(&argv[0])
    };
    match parse_inner(argv, &prog) {
        Ok(opts) => {
            if opts.no_clobber && opts.force {
                return ParseResult::AppError(
                    "Invalid arguments: --force and --noclobber cannot be set at the same time.".to_string()
                );
            }
            ParseResult::Ok(opts)
        }
        Err(err) => err,
    }
}

fn parse_inner(argv: Vec<OsString>, prog: &str) -> Result<Options, ParseResult> {
    let mut opts = Options {
        verbose: 0,
        recursive: false,
        dereference: false,
        workers: 4,
        block_size: 1024 * 1024, // 1MB
        no_clobber: false,
        force: false,
        gitignore: false,
        glob: false,
        no_progress: false,
        no_perms: false,
        no_timestamps: false,
        ownership: false,
        driver: Driver::ParFile,
        no_target_directory: false,
        target_directory: None,
        fsync: false,
        reflink: Reflink::Auto,
        backup: Backup::None,
        paths: Vec::new(),
    };

    let mut positional_only = false;
    let mut args_iter = argv.into_iter();
    let _argv0 = args_iter.next();
    let args: Vec<OsString> = args_iter.collect();
    let mut i = 0;
    while i < args.len() {
        let cur = args[i].clone();
        let cur_s = cur.to_string_lossy().into_owned();

        if positional_only {
            opts.paths.push(PathBuf::from(cur));
            i += 1;
            continue;
        }

        if cur_s == "--" {
            positional_only = true;
            i += 1;
            continue;
        }

        if cur_s.starts_with("--") {
            let body = &cur_s[2..];
            let (name, value_inline): (&str, Option<String>) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            match name {
                "help" => {
                    if value_inline.is_some() {
                        return Err(ParseResult::ClapError(fmt_bool_with_value_err(
                            prog, "--help", value_inline.as_deref().unwrap_or(""),
                        )));
                    }
                    return Err(ParseResult::Help(long_help(prog)));
                }
                "version" => {
                    if value_inline.is_some() {
                        return Err(ParseResult::ClapError(fmt_bool_with_value_err(
                            prog, "--version", value_inline.as_deref().unwrap_or(""),
                        )));
                    }
                    return Err(ParseResult::Version(version_text()));
                }
                "verbose" => {
                    if value_inline.is_some() {
                        return Err(ParseResult::ClapError(fmt_bool_with_value_err(
                            prog, "--verbose", value_inline.as_deref().unwrap_or(""),
                        )));
                    }
                    opts.verbose = opts.verbose.saturating_add(1);
                }
                "recursive" => { opts.recursive = true; bool_check(prog, "--recursive", &value_inline)?; }
                "dereference" => { opts.dereference = true; bool_check(prog, "--dereference", &value_inline)?; }
                "workers" => {
                    let val = take_value(&mut i, &args, "--workers <WORKERS>", &value_inline, prog)?;
                    match val.parse::<i64>() {
                        Ok(v) => opts.workers = v,
                        Err(e) => return Err(ParseResult::ClapError(fmt_invalid_value(
                            prog, "--workers <WORKERS>", &val, &e.to_string()
                        ))),
                    }
                }
                "block-size" => {
                    let val = take_value(&mut i, &args, "--block-size <BLOCK_SIZE>", &value_inline, prog)?;
                    match bytesize::parse_bytes(&val) {
                        Ok(v) => opts.block_size = v,
                        Err(e) => return Err(ParseResult::ClapError(fmt_invalid_value(
                            prog, "--block-size <BLOCK_SIZE>", &val, &e.to_string()
                        ))),
                    }
                }
                "no-clobber" => { opts.no_clobber = true; bool_check(prog, "--no-clobber", &value_inline)?; }
                "force" => { opts.force = true; bool_check(prog, "--force", &value_inline)?; }
                "gitignore" => { opts.gitignore = true; bool_check(prog, "--gitignore", &value_inline)?; }
                "glob" => { opts.glob = true; bool_check(prog, "--glob", &value_inline)?; }
                "no-progress" => { opts.no_progress = true; bool_check(prog, "--no-progress", &value_inline)?; }
                "no-perms" => { opts.no_perms = true; bool_check(prog, "--no-perms", &value_inline)?; }
                "no-timestamps" => { opts.no_timestamps = true; bool_check(prog, "--no-timestamps", &value_inline)?; }
                "ownership" => { opts.ownership = true; bool_check(prog, "--ownership", &value_inline)?; }
                "driver" => {
                    let val = take_value(&mut i, &args, "--driver <DRIVER>", &value_inline, prog)?;
                    opts.driver = match val.as_str() {
                        "parfile" => Driver::ParFile,
                        "parblock" => Driver::ParBlock,
                        _ => return Err(ParseResult::ClapError(fmt_invalid_value(
                            prog, "--driver <DRIVER>", &val, &format!("Unknown driver: {}", val),
                        ))),
                    };
                }
                "no-target-directory" => { opts.no_target_directory = true; bool_check(prog, "--no-target-directory", &value_inline)?; }
                "target-directory" => {
                    let val = take_value(&mut i, &args, "--target-directory <TARGET_DIRECTORY>", &value_inline, prog)?;
                    opts.target_directory = Some(PathBuf::from(val));
                }
                "fsync" => { opts.fsync = true; bool_check(prog, "--fsync", &value_inline)?; }
                "reflink" => {
                    let val = take_value(&mut i, &args, "--reflink <REFLINK>", &value_inline, prog)?;
                    opts.reflink = match val.as_str() {
                        "auto" => Reflink::Auto,
                        "always" => Reflink::Always,
                        "never" => Reflink::Never,
                        _ => return Err(ParseResult::ClapError(fmt_invalid_value(
                            prog, "--reflink <REFLINK>", &val,
                            &format!("Invalid arguments: Unexpected value for 'reflink': {}", val),
                        ))),
                    };
                }
                "backup" => {
                    let val = take_value(&mut i, &args, "--backup <BACKUP>", &value_inline, prog)?;
                    opts.backup = match val.as_str() {
                        "none" | "off" => Backup::None,
                        "numbered" => Backup::Numbered,
                        "auto" => Backup::Auto,
                        _ => return Err(ParseResult::ClapError(fmt_invalid_value(
                            prog, "--backup <BACKUP>", &val,
                            &format!("Invalid arguments: Unexpected value for 'backup': {}", val),
                        ))),
                    };
                }
                _ => return Err(ParseResult::ClapError(fmt_unknown_arg(prog, &cur_s))),
            }
            i += 1;
            continue;
        }

        if cur_s.starts_with('-') && cur_s.len() > 1 {
            let rest = &cur_s[1..];
            let chars: Vec<char> = rest.chars().collect();
            let mut idx = 0;
            let mut break_to_outer = false;
            while idx < chars.len() && !break_to_outer {
                let ch = chars[idx];
                match ch {
                    'h' => return Err(ParseResult::Help(short_help(prog))),
                    'V' => return Err(ParseResult::Version(version_text())),
                    'v' => opts.verbose = opts.verbose.saturating_add(1),
                    'r' => opts.recursive = true,
                    'L' => opts.dereference = true,
                    'n' => opts.no_clobber = true,
                    'f' => opts.force = true,
                    'g' => opts.glob = true,
                    'o' => opts.ownership = true,
                    'T' => opts.no_target_directory = true,
                    'w' => {
                        let remaining: String = chars[idx + 1..].iter().collect();
                        let val = if !remaining.is_empty() {
                            idx = chars.len();
                            remaining
                        } else {
                            i += 1;
                            if i >= args.len() {
                                return Err(ParseResult::ClapError(fmt_missing_value(prog, "--workers <WORKERS>")));
                            }
                            args[i].to_string_lossy().into_owned()
                        };
                        match val.parse::<i64>() {
                            Ok(v) => opts.workers = v,
                            Err(e) => return Err(ParseResult::ClapError(fmt_invalid_value(
                                prog, "--workers <WORKERS>", &val, &e.to_string()
                            ))),
                        }
                        break_to_outer = true;
                    }
                    _ => return Err(ParseResult::ClapError(fmt_unknown_arg(prog, &cur_s))),
                }
                idx += 1;
            }
            i += 1;
            continue;
        }

        opts.paths.push(PathBuf::from(cur));
        i += 1;
    }

    Ok(opts)
}

fn take_value(
    i: &mut usize,
    args: &[OsString],
    spec: &str,
    inline: &Option<String>,
    prog: &str,
) -> Result<String, ParseResult> {
    if let Some(v) = inline {
        return Ok(v.clone());
    }
    *i += 1;
    if *i >= args.len() {
        return Err(ParseResult::ClapError(fmt_missing_value(prog, spec)));
    }
    Ok(args[*i].to_string_lossy().into_owned())
}

fn bool_check(prog: &str, name: &str, val: &Option<String>) -> Result<(), ParseResult> {
    if let Some(v) = val {
        return Err(ParseResult::ClapError(fmt_bool_with_value_err(prog, name, v)));
    }
    Ok(())
}

pub fn version_text() -> String {
    format!("{} {}\n", PROG_NAME, VERSION)
}

// Clap-like error formatting -------------------------------------------------

fn fmt_unknown_arg(prog: &str, arg: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!("error: unexpected argument '{}' found\n\n", arg));
    out.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", arg, arg));
    out.push_str(&format!("Usage: {} [OPTIONS] [PATHS]...\n\n", prog));
    out.push_str("For more information, try '--help'.\n");
    out
}

fn fmt_invalid_value(prog: &str, spec: &str, val: &str, err: &str) -> String {
    // spec is like "--workers <WORKERS>", usage line shows the option only.
    let opt = spec.split_whitespace().next().unwrap_or(spec);
    let mut out = String::new();
    out.push_str(&format!(
        "error: invalid value '{}' for '{}': {}\n\n",
        val, spec, err
    ));
    out.push_str(&format!("For more information, try '--help'.\n"));
    let _ = opt; // unused variant
    out
}

fn fmt_missing_value(prog: &str, spec: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "error: a value is required for '{}' but none was supplied\n\n",
        spec
    ));
    out.push_str("For more information, try '--help'.\n");
    let _ = prog;
    out
}

fn fmt_bool_with_value_err(prog: &str, name: &str, val: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "error: unexpected value '{}' for '{}' found; no more were expected\n\n",
        val, name
    ));
    out.push_str(&format!("Usage: {} {} [PATHS]...\n\n", prog, name));
    out.push_str("For more information, try '--help'.\n");
    out
}

