//! The core copy runner.
use std::fmt;
use std::fs;
use std::io;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};

use crate::cli::{Backup, Options, Reflink};
use crate::gitignore::GitIgnore;
use crate::glob;

#[derive(Debug)]
pub enum XcpError {
    InvalidArguments(String),
    InvalidSource(String),
    InvalidDestination(String),
    DestinationExists(String, PathBuf),
    CopyError(String),
    IoError(io::Error),
}

impl fmt::Display for XcpError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            XcpError::InvalidArguments(m) => write!(f, "Invalid arguments: {}", m),
            XcpError::InvalidSource(m) => write!(f, "Invalid source: {}", m),
            XcpError::InvalidDestination(m) => write!(f, "Invalid destination: {}", m),
            XcpError::DestinationExists(m, p) => write!(f, "Destination Exists: {}, {}", m, p.display()),
            XcpError::CopyError(m) => write!(f, "Error during copy: {}", m),
            XcpError::IoError(e) => write!(f, "IO error: {}", e),
        }
    }
}

impl From<io::Error> for XcpError {
    fn from(e: io::Error) -> Self {
        XcpError::CopyError(e.to_string())
    }
}

pub fn run(opts: &Options) -> Result<(), XcpError> {
    if opts.paths.is_empty() {
        return Err(XcpError::InvalidArguments("Insufficient arguments".to_string()));
    }

    // Determine sources and dest.
    let (sources, dest) = if let Some(td) = &opts.target_directory {
        // `target-directory` supplies the destination.
        (opts.paths.clone(), td.clone())
    } else {
        if opts.paths.len() < 2 {
            return Err(XcpError::InvalidArguments("Insufficient arguments".to_string()));
        }
        let mut paths = opts.paths.clone();
        let dest = paths.pop().unwrap();
        (paths, dest)
    };

    // Expand globs if requested.
    let mut expanded: Vec<PathBuf> = Vec::new();
    if opts.glob {
        for src in &sources {
            let s = src.to_string_lossy().into_owned();
            if glob::has_glob_chars(&s) {
                let mut matches = glob::expand(&s);
                matches.sort();
                expanded.extend(matches);
            } else {
                expanded.push(src.clone());
            }
        }
    } else {
        expanded.extend(sources);
    }

    if expanded.is_empty() {
        return Err(XcpError::InvalidSource("No source files found.".to_string()));
    }

    // If globbing yielded *only* existing paths, great; otherwise we still
    // validate below.

    // Check sources exist.
    for s in &expanded {
        if !path_exists(s, opts.dereference) {
            return Err(XcpError::InvalidSource("Source does not exist.".to_string()));
        }
    }

    let dest_is_dir = is_dir(&dest, opts.dereference);

    // Multi-source requires destination-as-dir.
    if expanded.len() > 1 && !dest_is_dir {
        return Err(XcpError::InvalidDestination(
            "Multiple sources and destination is not a directory.".to_string()
        ));
    }

    // Fire warning for --reflink=never.
    if matches!(opts.reflink, Reflink::Never) {
        crate::log_warn!("--reflink=never is selected, however the Linux kernel may override this.");
    }

    // Single source logging.
    if expanded.len() == 1 {
        let dst_final = compute_dest_for(&expanded[0], &dest, dest_is_dir, opts);
        crate::log_info!(
            "Copying source {:?} to {:?}",
            expanded[0].as_os_str(),
            dst_final.as_os_str()
        );
    } else {
        crate::log_info!("Copying multiple sources to {:?}", dest.as_os_str());
    }

    for src in &expanded {
        let dst = compute_dest_for(src, &dest, dest_is_dir, opts);
        let meta = lstat(src, opts.dereference)?;
        if meta.file_type().is_dir() {
            if !opts.recursive {
                return Err(XcpError::InvalidSource(
                    "Source is directory and --recursive not specified.".to_string()
                ));
            }
            copy_dir(src, &dst, opts)?;
        } else {
            copy_single_entry(src, &dst, &meta, opts)?;
        }
    }

    crate::log_info!("Copy complete");
    Ok(())
}

fn compute_dest_for(src: &Path, dest: &Path, dest_is_dir: bool, opts: &Options) -> PathBuf {
    if opts.no_target_directory {
        dest.to_path_buf()
    } else if dest_is_dir {
        if let Some(name) = src.file_name() {
            dest.join(name)
        } else {
            dest.to_path_buf()
        }
    } else {
        dest.to_path_buf()
    }
}

fn path_exists(p: &Path, deref: bool) -> bool {
    if deref {
        fs::metadata(p).is_ok()
    } else {
        fs::symlink_metadata(p).is_ok()
    }
}

fn is_dir(p: &Path, deref: bool) -> bool {
    if deref {
        fs::metadata(p).map(|m| m.is_dir()).unwrap_or(false)
    } else {
        fs::metadata(p).map(|m| m.is_dir()).unwrap_or(false)
    }
}

fn lstat(p: &Path, deref: bool) -> Result<fs::Metadata, XcpError> {
    if deref {
        fs::metadata(p).map_err(|e| XcpError::CopyError(e.to_string()))
    } else {
        fs::symlink_metadata(p).map_err(|e| XcpError::CopyError(e.to_string()))
    }
}

fn copy_dir(src: &Path, dst: &Path, opts: &Options) -> Result<(), XcpError> {
    // Optional gitignore from the source root.
    let gitignore: Option<GitIgnore> = if opts.gitignore {
        let gipath = src.join(".gitignore");
        if let Ok(text) = fs::read_to_string(&gipath) {
            Some(GitIgnore::parse(&text))
        } else {
            None
        }
    } else {
        None
    };

    // Ensure destination root.
    match fs::create_dir(dst) {
        Ok(()) => {}
        Err(e) if e.kind() == io::ErrorKind::AlreadyExists => {
            if opts.no_clobber {
                return Err(XcpError::DestinationExists(
                    "Destination file exists and --no-clobber is set.".to_string(),
                    dst.to_path_buf(),
                ));
            }
        }
        Err(e) => return Err(XcpError::CopyError(e.to_string())),
    }

    walk_and_copy(src, dst, src, opts, gitignore.as_ref())
}

fn walk_and_copy(
    root_src: &Path,
    root_dst: &Path,
    cur_src: &Path,
    opts: &Options,
    gitignore: Option<&GitIgnore>,
) -> Result<(), XcpError> {
    let entries = match fs::read_dir(cur_src) {
        Ok(e) => e,
        Err(e) => {
            crate::log_error!(
                "Error copying: {:?} -> {:?}; aborting.",
                cur_src.as_os_str(),
                root_dst.as_os_str()
            );
            return Err(XcpError::CopyError(e.to_string()));
        }
    };
    let mut names: Vec<PathBuf> = Vec::new();
    for e in entries.flatten() {
        names.push(e.path());
    }
    names.sort();

    for entry_path in names {
        let rel = entry_path.strip_prefix(root_src).unwrap();
        // gitignore based on relative to root_src
        if let Some(gi) = gitignore {
            let meta = fs::symlink_metadata(&entry_path)
                .map_err(|e| XcpError::CopyError(e.to_string()))?;
            if gi.is_ignored(rel, meta.is_dir()) {
                continue;
            }
        }
        let dest_path = root_dst.join(rel);

        let meta = if opts.dereference {
            fs::metadata(&entry_path)
        } else {
            fs::symlink_metadata(&entry_path)
        }
        .map_err(|e| XcpError::CopyError(e.to_string()))?;

        let ft = meta.file_type();
        if ft.is_dir() {
            match fs::create_dir(&dest_path) {
                Ok(()) => {}
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists => {
                    if opts.no_clobber {
                        return Err(XcpError::DestinationExists(
                            "Destination file exists and --no-clobber is set.".to_string(),
                            dest_path,
                        ));
                    }
                }
                Err(e) => return Err(XcpError::CopyError(e.to_string())),
            }
            walk_and_copy(root_src, root_dst, &entry_path, opts, gitignore)?;
        } else {
            copy_single_entry(&entry_path, &dest_path, &meta, opts)?;
        }
    }
    Ok(())
}

fn copy_single_entry(
    src: &Path,
    dst: &Path,
    meta: &fs::Metadata,
    opts: &Options,
) -> Result<(), XcpError> {
    // Handle --no-clobber and backup.
    if dst.exists() || fs::symlink_metadata(dst).is_ok() {
        if opts.no_clobber {
            return Err(XcpError::DestinationExists(
                "Destination file exists and --no-clobber is set.".to_string(),
                dst.to_path_buf(),
            ));
        }
        maybe_backup(dst, opts)?;
    }

    let ft = meta.file_type();
    if ft.is_symlink() {
        let target = fs::read_link(src).map_err(|e| XcpError::CopyError(e.to_string()))?;
        let _ = fs::remove_file(dst);
        std::os::unix::fs::symlink(&target, dst)
            .map_err(|e| XcpError::CopyError(e.to_string()))?;
    } else if ft.is_fifo() || ft.is_block_device() || ft.is_char_device() || ft.is_socket() {
        // Recreate via mknod.
        mknod(dst, meta)?;
    } else if ft.is_file() {
        copy_file_contents(src, dst, opts)?;
        if !opts.no_perms {
            let mode = meta.permissions().mode();
            let _ = fs::set_permissions(dst, fs::Permissions::from_mode(mode));
        }
        if !opts.no_timestamps {
            copy_times(src, dst, meta);
        }
        if opts.ownership {
            let _ = chown(dst, meta.uid(), meta.gid());
        }
    } else {
        return Err(XcpError::CopyError(format!("Unsupported file type: {:?}", src)));
    }

    Ok(())
}

fn maybe_backup(dst: &Path, opts: &Options) -> Result<(), XcpError> {
    match opts.backup {
        Backup::None => Ok(()),
        Backup::Numbered => {
            let backup = next_backup(dst);
            fs::rename(dst, &backup).map_err(|e| XcpError::CopyError(e.to_string()))?;
            Ok(())
        }
        Backup::Auto => {
            if has_existing_backup(dst) {
                let backup = next_backup(dst);
                fs::rename(dst, &backup).map_err(|e| XcpError::CopyError(e.to_string()))?;
            }
            Ok(())
        }
    }
}

fn has_existing_backup(dst: &Path) -> bool {
    let parent = dst.parent().unwrap_or_else(|| Path::new("."));
    let fname = match dst.file_name() {
        Some(n) => n.to_string_lossy().into_owned(),
        None => return false,
    };
    let prefix = format!("{}.~", fname);
    if let Ok(rd) = fs::read_dir(parent) {
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().into_owned();
            if name.starts_with(&prefix) && name.ends_with('~') {
                let mid = &name[prefix.len()..name.len() - 1];
                if !mid.is_empty() && mid.chars().all(|c| c.is_ascii_digit()) {
                    return true;
                }
            }
        }
    }
    false
}

fn next_backup(dst: &Path) -> PathBuf {
    let parent = dst.parent().unwrap_or_else(|| Path::new("."));
    let fname = dst.file_name().unwrap().to_string_lossy().into_owned();
    let prefix = format!("{}.~", fname);
    let mut max: u32 = 0;
    if let Ok(rd) = fs::read_dir(parent) {
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().into_owned();
            if name.starts_with(&prefix) && name.ends_with('~') {
                let mid = &name[prefix.len()..name.len() - 1];
                if let Ok(n) = mid.parse::<u32>() {
                    if n > max {
                        max = n;
                    }
                }
            }
        }
    }
    parent.join(format!("{}.~{}~", fname, max + 1))
}

fn copy_file_contents(src: &Path, dst: &Path, opts: &Options) -> Result<(), XcpError> {
    // The parent may need to be created if we're copying into a sub-path; but
    // the caller typically creates parents.
    crate::log_info!(
        "Worker[ThreadId(4)]: Copy {:?} -> {:?}",
        src.as_os_str(),
        dst.as_os_str()
    );
    match do_copy(src, dst, opts) {
        Ok(_) => Ok(()),
        Err(e) => {
            crate::log_error!(
                "Error copying: {:?} -> {:?}; aborting.",
                src.as_os_str(),
                dst.as_os_str()
            );
            Err(XcpError::CopyError(e.to_string()))
        }
    }
}

fn do_copy(src: &Path, dst: &Path, opts: &Options) -> io::Result<u64> {
    // Ensure dest doesn't already exist as directory: let fs::copy fail
    // naturally to produce "Is a directory" error.
    let bytes = fs::copy(src, dst)?;
    if opts.fsync {
        if let Ok(f) = fs::File::open(dst) {
            let _ = f.sync_all();
        }
    }
    Ok(bytes)
}

fn mknod(dst: &Path, meta: &fs::Metadata) -> Result<(), XcpError> {
    extern "C" {
        fn mknod(pathname: *const i8, mode: u32, dev: u64) -> i32;
        fn __errno_location() -> *mut i32;
    }
    let c_path = std::ffi::CString::new(dst.as_os_str().as_encoded_bytes())
        .map_err(|e| XcpError::CopyError(e.to_string()))?;
    let mode = meta.mode();
    let dev = meta.rdev();
    let rc = unsafe { mknod(c_path.as_ptr() as *const i8, mode, dev) };
    if rc != 0 {
        let err = io::Error::from_raw_os_error(unsafe { *__errno_location() });
        return Err(XcpError::CopyError(err.to_string()));
    }
    Ok(())
}

fn copy_times(src: &Path, dst: &Path, meta: &fs::Metadata) {
    #[repr(C)]
    struct Timespec {
        tv_sec: i64,
        tv_nsec: i64,
    }
    extern "C" {
        fn utimensat(dirfd: i32, pathname: *const i8, times: *const Timespec, flags: i32) -> i32;
    }
    let _ = src;
    let c_path = match std::ffi::CString::new(dst.as_os_str().as_encoded_bytes()) {
        Ok(c) => c,
        Err(_) => return,
    };
    let atime = Timespec {
        tv_sec: meta.atime(),
        tv_nsec: meta.atime_nsec(),
    };
    let mtime = Timespec {
        tv_sec: meta.mtime(),
        tv_nsec: meta.mtime_nsec(),
    };
    let times = [atime, mtime];
    unsafe {
        utimensat(-100 /* AT_FDCWD */, c_path.as_ptr() as *const i8, times.as_ptr(), 0);
    }
}

fn chown(dst: &Path, uid: u32, gid: u32) -> io::Result<()> {
    extern "C" {
        fn chown(pathname: *const i8, owner: u32, group: u32) -> i32;
        fn __errno_location() -> *mut i32;
    }
    let c_path = std::ffi::CString::new(dst.as_os_str().as_encoded_bytes())
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;
    let rc = unsafe { chown(c_path.as_ptr() as *const i8, uid, gid) };
    if rc != 0 {
        return Err(io::Error::from_raw_os_error(unsafe { *__errno_location() }));
    }
    Ok(())
}
